-- Hand-written (TD-2 pattern): a Prisma-autogenerated migration for an enum
-- value rename would DROP and RECREATE the "FlightType" enum (and cast the
-- column through text), which is unnecessary churn and briefly invalidates
-- the column's type. `ALTER TYPE ... RENAME VALUE` is transactional and
-- in-place: no index or constraint references the enum values (verified),
-- so this is safe.

-- RenameEnumValue
ALTER TYPE "FlightType" RENAME VALUE 'PRIVATE' TO 'TOURISM';

-- RenameEnumValue
ALTER TYPE "FlightType" RENAME VALUE 'OTHER' TO 'AERIAL_WORK';

-- AddColumn
ALTER TABLE "Flight" ADD COLUMN "isSolo" BOOLEAN NOT NULL DEFAULT false;
